16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 (a '+' followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Column(name = "household_size")
67	    private Integer householdSize;
68	
69	    // Create-time signal only: derived from the count of owners already created today, not an
70	    // intrinsic owner attribute, so it is never persisted. Defaults to false, which is what a
71	    // reloaded owner (e.g. served by GET) reports.
72	    @Transient
73	    private boolean bulkSignupWarning;
74	
75	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
76	    private Set<Pet> pets;
77	
78	    public String getAddress() {
79	        return this.address;
80	    }
81	
82	    public void setAddress(String address) {
83	        this.address = address;
84	    }
85	
86	    public String getCity() {
87	        return this.city;
88	    }
89	
90	    public void setCity(String city) {
91	        this.city = city;
92	    }
93	
94	    public String getTelephone() {
95	        return this.telephone;
96	    }
97	
98	    public void setTelephone(String telephone) {
99	        this.telephone = telephone;
100	    }
101	
102	    public String getEmail() {
103	        return this.email;
104	    }
105	
106	    public void setEmail(String email) {
107	        this.email = email;
108	    }
109	
110	    public LocalDate getRegistrationDate() {
111	        return this.registrationDate;
112	    }
113	
114	    public void setRegistrationDate(LocalDate registrationDate) {
115	        this.registrationDate = registrationDate;
116	    }
117	
118	    public String getCustomerCode() {
119	        return this.customerCode;
120	    }
121	
122	    public void setCustomerCode(String customerCode) {
123	        this.customerCode = customerCode;
124	    }
125	
126	    public String getHouseholdId() {
127	        return this.householdId;
128	    }
129	
130	    public void setHouseholdId(String householdId) {
131	        this.householdId = householdId;
132	    }
133	
134	    public Integer getNamesakeCount() {
135	        return this.namesakeCount;
136	    }
137	
138	    public void setNamesakeCount(Integer namesakeCount) {
139	        this.namesakeCount = namesakeCount;
140	    }
141	
142	    public Integer getHouseholdSize() {
143	        return this.householdSize;
144	    }
145	
146	    public void setHouseholdSize(Integer householdSize) {
147	        this.householdSize = householdSize;
148	    }
149	
150	    public boolean isBulkSignupWarning() {
151	        return this.bulkSignupWarning;
152	    }
153	
154	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
155	        this.bulkSignupWarning = bulkSignupWarning;
156	    }
157	
158	    protected Set<Pet> getPetsInternal() {
159	        if (this.pets == null) {
160	            this.pets = new HashSet<>();
161	        }
162	        return this.pets;
163	    }
164	
165	    protected void setPetsInternal(Set<Pet> pets) {
166	        this.pets = pets;
167	    }
168	
169	    public List<Pet> getPets() {
170	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
171	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
172	        return Collections.unmodifiableList(sortedPets);
173	    }
174	
175	    public void setPets(List<Pet> pets) {
176	        this.pets = new HashSet<>(pets);
177	    }
178	
179	    public void addPet(Pet pet) {
180	        getPetsInternal().add(pet);
181	        pet.setOwner(this);
182	    }
183	
184	    /**
185	     * Return the Pet with the given name, or null if none found for this Owner.
186	     *
187	     * @param name to test
188	     * @return true if pet name is already in use
189	     */
190	    public Pet getPet(String name) {
191	        return getPet(name, false);
192	    }
193	
194	    /**
195	     * Return the Pet with the given name, or null if none found for this Owner.
196	     *
197	     * @param name to test
198	     * @return true if pet name is already in use
199	     */
200	    public Pet getPet(String name, boolean ignoreNew) {
201	        name = name.toLowerCase();
202	        for (Pet pet : getPetsInternal()) {
203	            if (!ignoreNew || !pet.isNew()) {
204	                String compName = pet.getName();
205	                compName = compName.toLowerCase();
206	                if (compName.equals(name)) {
207	                    return pet;
208	                }
209	            }
210	        }
211	        return null;
212	    }
213	
214	    public Pet getPet(Integer petId) {
215	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
216	    }
217	
218	    @Override
219	    public String toString() {
220	        return new ToStringCreator(this)
221	
222	            .append("id", this.getId())
223	            .append("new", this.isNew())
224	            .append("lastName", this.getLastName())
225	            .append("firstName", this.getFirstName())
226	            .append("address", this.address)
227	            .append("city", this.city)
228	            .append("telephone", this.telephone)
229	            .append("email", this.email)
230	            .toString();
231	    }
232	}
