1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Rejects a create request whose telephone is already used by another owner, so a
11	 * duplicate is a 409. Runs after {@link ValidateOwnerFields} has normalized the telephone
12	 * to E.164 form, comparing against every existing owner's telephone in E.164 form so that
13	 * national and international spellings of the same number collide.
14	 */
15	public class EnsureUniqueTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = TelephoneE164.normalize(request.getTelephone());
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone != null && telephone.equals(TelephoneE164.normalize(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(telephone);
23	            }
24	        }
25	    }
26	}
