1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;
10	
11	/**
12	 * Rejects a create request whose email is already used by another owner, so a duplicate is
13	 * a 409. Email is optional: a request with no email skips the check. Comparison is
14	 * case-insensitive — both the request email (already lower-cased by
15	 * {@link ValidateOwnerFields}) and every existing owner's email are lower-cased — so
16	 * "Jo@Example.test" and "jo@example.test" collide.
17	 */
18	public class EnsureUniqueEmail {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateEmailException {
22	        String email = normalize(request.getEmail());
23	        if (email == null) {
24	            return;
25	        }
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (email.equals(normalize(existing.getEmail()))) {
28	                throw new DuplicateEmailException(email);
29	            }
30	        }
31	    }
32	
33	    /** Trim and lower-case; null or blank yields null (nothing to compare). */
34	    private static String normalize(String value) {
35	        if (value == null || value.isBlank()) {
36	            return null;
37	        }
38	        return value.trim().toLowerCase(Locale.ROOT);
39	    }
40	}
