1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
10	
11	/**
12	 * Rejects a create request whose lastName and address together already identify another
13	 * owner, so a household duplicate is a 409. lastName is compared case-insensitively with
14	 * collapsed whitespace, so " Smith " and "smith" collide. address is compared in its
15	 * normalized form (see {@link AddressNormalizer}), so "12 Main St" and "12  main  street"
16	 * collide. A request may opt out of this check by setting {@code sharesHousehold} true,
17	 * allowing several owners at one household.
18	 */
19	public class EnsureUniqueHousehold {
20	
21	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
22	            throws DuplicateHouseholdException {
23	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
24	            return;
25	        }
26	        String lastName = normalize(request.getLastName());
27	        String address = AddressNormalizer.normalize(request.getAddress());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (lastName.equals(normalize(existing.getLastName()))
30	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))) {
31	                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
32	            }
33	        }
34	    }
35	
36	    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
37	     *  single space, and lower-case. */
38	    private static String normalize(String value) {
39	        if (value == null) {
40	            return "";
41	        }
42	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
43	    }
44	}
