1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Map;
4	import java.util.regex.Pattern;
5	
6	/**
7	 * Converts a raw telephone string to E.164 form: keep a leading '+' and country code
8	 * when present, otherwise assume country code '+61' and drop a single leading '0' from
9	 * the national digits. Spaces, dashes and brackets are stripped, and the result must
10	 * carry 8 to 15 digits after the '+'. For recognised country codes the national-number
11	 * length is checked exactly ('+61' requires 9 national digits, '+1' requires 10); a
12	 * wrong length is rejected. Returns {@code null} when no valid E.164 number can be
13	 * formed, so callers reject with a 400.
14	 */
15	final class TelephoneE164 {
16	
17	    /** E.164: a '+' followed by 8 to 15 digits. */
18	    private static final Pattern E164 = Pattern.compile("\\d{8,15}");
19	
20	    /**
21	     * Required national-number length per country code. No key is a prefix of another
22	     * (the recognised codes '61' and '1' do not overlap), so prefix matching is
23	     * unambiguous regardless of iteration order.
24	     */
25	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of(
26	            "61", 9,
27	            "1", 10);
28	
29	    private TelephoneE164() {
30	    }
31	
32	    static String normalize(String raw) {
33	        if (raw == null) {
34	            return null;
35	        }
36	        // Strip spaces, dashes and brackets; a leading '+' (after trimming) is significant.
37	        String stripped = raw.trim().replaceAll("[\\s\\-()]", "");
38	        String digits;
39	        if (stripped.startsWith("+")) {
40	            // Keep the caller's country code as-is.
41	            digits = stripped.substring(1);
42	        }
43	        else {
44	            // National number: assume '+61' and drop a single leading '0'.
45	            String national = stripped.startsWith("0") ? stripped.substring(1) : stripped;
46	            digits = "61" + national;
47	        }
48	        if (!E164.matcher(digits).matches()) {
49	            return null;
50	        }
51	        // For a recognised country code, the national number must be exactly the right
52	        // length; other codes keep only the general 8-to-15-digit rule above.
53	        for (Map.Entry<String, Integer> code : NATIONAL_LENGTHS.entrySet()) {
54	            if (digits.startsWith(code.getKey())) {
55	                int nationalLength = digits.length() - code.getKey().length();
56	                if (nationalLength != code.getValue()) {
57	                    return null;
58	                }
59	                break;
60	            }
61	        }
62	        return "+" + digits;
63	    }
64	}
