1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.Locale;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.repository.OwnerRepository;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * When a create request opts in with {@code sharesHousehold} true, joins the new owner to
14	 * the household identified by its lastName (compared case-insensitively with collapsed
15	 * whitespace) and address (compared in its normalized form; see
16	 * {@link AddressNormalizer}), matching {@link EnsureUniqueHousehold}. The household's
17	 * stable shared {@code householdId} is derived deterministically from that
18	 * lastName/address, so every member computes the same value. The new owner and every already-stored member of
19	 * the household are assigned that identifier, so both sides of a join share it.
20	 *
21	 * <p>Runs after {@code build}, so the new Owner entity exists but is not yet saved (and so
22	 * is not among the existing members backfilled here). A request that does not set
23	 * {@code sharesHousehold} leaves {@code householdId} null.
24	 */
25	public class AssignHousehold {
26	
27	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
28	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
29	            return;
30	        }
31	        String lastName = normalize(owner.getLastName());
32	        String address = AddressNormalizer.normalize(owner.getAddress());
33	        String householdId = householdId(lastName, address);
34	        owner.setHouseholdId(householdId);
35	        for (Owner existing : ownerRepository.findAll()) {
36	            if (lastName.equals(normalize(existing.getLastName()))
37	                    && address.equals(AddressNormalizer.normalize(existing.getAddress()))
38	                    && !householdId.equals(existing.getHouseholdId())) {
39	                existing.setHouseholdId(householdId);
40	                ownerRepository.save(existing);
41	            }
42	        }
43	    }
44	
45	    /** Stable 12-hex-char uppercase identifier for a household, derived from its normalized
46	     *  lastName and address so every member of the same household computes the same value. */
47	    private static String householdId(String lastName, String address) {
48	        return sha256hex(lastName + "\n" + address).substring(0, 12).toUpperCase(Locale.ROOT);
49	    }
50	
51	    private static String sha256hex(String value) {
52	        try {
53	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
54	            StringBuilder sb = new StringBuilder(digest.length * 2);
55	            for (byte b : digest) {
56	                sb.append(String.format("%02x", b));
57	            }
58	            return sb.toString();
59	        }
60	        catch (Exception e) {
61	            throw new RuntimeException(e);
62	        }
63	    }
64	
65	    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
66	     *  single space, and lower-case. Mirrors {@link EnsureUniqueHousehold}. */
67	    private static String normalize(String value) {
68	        if (value == null) {
69	            return "";
70	        }
71	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
72	    }
73	}
