3	/**
4	 * Thrown when a create request supplies a normalized telephone already used by another
5	 * owner. Handled by {@link DuplicateTelephoneExceptionHandler}, which responds 409.
6	 */
7	public class DuplicateTelephoneException extends Exception {
8	
9	    public DuplicateTelephoneException(String telephone) {
10	        super("Telephone already in use: " + telephone);
11	    }
12	}
