7	/**
8	 * Assigns the owner's {@code householdSize}: the number of members in the owner's household
9	 * (owners sharing the same {@code householdId}) after this create — the already-stored members
10	 * plus this new owner. Runs after {@link AssignHousehold} (so the new owner's {@code householdId}
11	 * is set and existing members are backfilled) and before {@code save} (so the new owner is not yet
12	 * counted among the stored members, and is instead added as the {@code + 1}).
13	 *
14	 * <p>An owner not part of a shared household ({@code householdId} null) has a household size of 1.
15	 */
16	public class AssignHouseholdSize {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        int count = 1; // this new owner, not yet saved
21	        if (householdId != null) {
22	            for (Owner existing : ownerRepository.findAll()) {
23	                if (householdId.equals(existing.getHouseholdId())) {
24	                    count++;
25	                }
26	            }
27	        }
28	        owner.setHouseholdSize(count);
29	    }
30	}
