20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws CityAtCapacityException {
22	        String city = normalize(request.getCity());
23	        int count = 0;
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (city.equals(normalize(existing.getCity()))) {
26	                count++;
27	            }
28	        }
29	        if (count >= CITY_CAPACITY) {
30	            throw new CityAtCapacityException(request.getCity());
31	        }
32	    }
33	
34	    /** Case-insensitive with collapsed whitespace: trim, fold internal whitespace runs to a
35	     *  single space, and lower-case. */
36	    private static String normalize(String value) {
37	        if (value == null) {
38	            return "";
39	        }
40	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
41	    }
42	}
